$count=0;$diff=array();function ib_norm($v){if(is_object($v)){$o=new stdClass();$p=get_object_vars($v);ksort($p);foreach($p as $k=>$x){if($k==='updated_at'){continue;}if($k==='last_error'&&is_string($x)&&$x!==''){$x='Message delivery reported an error.';}$o->$k=ib_norm($x);}return $o;}if(is_array($v)){return array_map('ib_norm',$v);}if(is_string($v)&&preg_match('/^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:/',$v)){return (new DateTimeImmutable($v,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}return $v;}
